            for (int j = 0; j < 3; j++) {
                if (((b >> (2 - j)) & 1) == 1) {
                    bParity ^= ((y >> (2 - j)) & 1);
                }
            }

            if (aParity == bParity) {
                count++;
            }
        }
        return count;
    }

    /**
     * Validate computed NLAT against expected values
