    public static int lat(int[][] input, int[][] output, int a, int b) {
        int count = 0;

        for (int x = 0; x < 8; x++) {
            int aParity = 0;
            for (int i = 0; i < 3; i++) {
                if ((a >> (2 - i) & 1) == 1) {
                    aParity ^= input[x][i];
                }
            }

            int bParity = 0;
            for (int j = 0; j < 3; j++) {
