```cpp
#include <iostream>
#include <vector>
#include <ctime>
#include <cstdlib>
#include <chrono>
#include <stack>

using namespace std;
using namespace chrono;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

void deleteTree(Node* root) {
    if (root) {
        deleteTree(root->left);
        deleteTree(root->right);
        delete root;
    }
}

void selectionSort(vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n; ++i) {
        int min_idx = i;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        swap(arr[i], arr[min_idx]);
    }
}

struct StackNode {
    int start;
    int end;
    Node* parent;
    bool isLeft;
};

Node* sortedArrayToBSTIterative(vector<int>& arr) {
    if (arr.empty()) return nullptr;

    int n = arr.size();
    stack<StackNode> stk;
    Node* root = nullptr;
    stk.push({0, n - 1, nullptr, false});

    while (!stk.empty()) {
        StackNode current = stk.top();
        stk.pop();

        int start = current.start;
        int end = current.end;
        Node* parent = current.parent;
        bool isLeft = current.isLeft;

        if (start > end) continue;

        int mid = (start + end) / 2;
        Node* node = new Node(arr[mid]);

        if (parent == nullptr) {
            root = node;
        } else {
            if (isLeft) {
                parent->left = node;
            } else {
                parent->right = node;
            }
        }

        // Push right first so that left is processed next
        stk.push({mid + 1, end, node, false}); // right
        stk.push({start, mid - 1, node, true}); // left
    }

    return root;
}

void inOrderTraversal(Node* node, vector<int>& result) {
    if (node) {
        inOrderTraversal(node->left, result);
        result.push_back(node->data);
        inOrderTraversal(node->right, result);
    }
}

int main() {
    srand(time(0));
    int n = 10; // Adjust for different test cases
    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        arr[i] = rand() % 100 + 1;
    }

    // Edge Case Examples:
    // vector<int> arr; // Empty input
    // vector<int> arr = {5,5,5,5}; // All duplicates

    cout << "Original array: ";
    for (int num : arr) cout << num << " ";
    cout << endl;

    // Selection Sort Timing
    vector<int> sortedArr = arr;
    auto start = high_resolution_clock::now();
    selectionSort(sortedArr);
    auto end = high_resolution_clock::now();
    double selectionTime = duration_cast<microseconds>(end - start).count() / 1e6;

    cout << "Sorted array: ";
    for (int num : sortedArr) cout << num << " ";
    cout << endl;
    cout << "Selection Sort Time: " << selectionTime << "s" << endl;

    // BST Creation Timing
    start = high_resolution_clock::now();
    Node* root = sortedArrayToBSTIterative(sortedArr);
    end = high_resolution_clock::now();
    double bstTime = duration_cast<microseconds>(end - start).count() / 1e6;
    cout << "BST Creation Time: " << bstTime << "s" << endl;

    // Verification
    vector<int> inOrder;
    inOrderTraversal(root, inOrder);
    cout << "In-order Traversal: ";
    for (int num : inOrder) cout << num << " ";
    cout << endl;

    // Validate BST structure
    bool correct = true;
    for (size_t i = 0; i < inOrder.size(); ++i) {
        if (inOrder[i] != sortedArr[i]) {
            correct = false;
            break;
        }
    }
    cout << "BST in-order traversal matches sorted array: " << (correct ? "Yes" : "No") << endl;

    // Total Time
    cout << "Total Time: " << (selectionTime + bstTime) << "s" << endl;

    // Memory cleanup
    deleteTree(root);

    return 0;
}
