# backend/markdown_validator.py
import mistune  # Markdown parser for validation
from datetime import datetime

class MarkdownValidator:
    def __init__(self):
        self.parser = mistune.Parser()
        self.renderer = mistune.HTMLRenderer()

    def validate_content(self, content: str) -> dict:
        """Validate markdown content and enforce documentation standards"""
        try:
            # Basic markdown validation
            ast = self.parser.parse(content)
            html = self.renderer.render(ast)

            # Enforce documentation standards
            issues = []
            if not content.startswith('# '):
                issues.append("Missing main heading (H1)")

            # Check for empty content
            if len(content.strip()) == 0:
                issues.append("Document cannot be empty")

            # Check image syntax
            if '!' in content and not all(['(' in content and ')' in content]):
                issues.append("Invalid image syntax detected")

            # Check for minimum content length
            if len(content.split('\n')) < 5:
                issues.append("Document too short (<5 lines)")

            # Check for basic list formatting
            if '- ' not in content and '*' not in content:
                issues.append("Missing proper list formatting")

            return {
                'valid': len(issues) == 0,
                'html_preview': html,
                'issues': issues,
                'word_count': len(content.split()),
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {
                'valid': False,
                'error': str(e),
                'issues': ['Invalid markdown syntax']
            }

# Example usage
if __name__ == "__main__":
    validator = MarkdownValidator()
    test_content = "# API Documentation\n\n## Introduction\n..."
    result = validator.validate_content(test_content)
    print("Validation Result:", result)
