using SkiaSharp;

public byte[] OptimizePng(string imagePath, int zlibLevel = 6, int? targetWidth = null, bool grayscale = false, int maxColors = 256)
{
    using var bitmap = SKBitmap.Decode(imagePath);
    SKImage resizedImage = null;

    // Resize if needed
    if (targetWidth.HasValue)
    {
        var height = (int)(bitmap.Height * (targetWidth.Value / (float)bitmap.Width));
        using var surface = new SKCanvas(new SKImageInfo(targetWidth.Value, height));
        surface.Scale((float)targetWidth / bitmap.Width, (float)height / bitmap.Height);
        surface.DrawImage(SKImage.FromBitmap(bitmap), 0, 0, new SKPaint { FilterQuality = SKFilterQuality.High });
        resizedImage = surface.Snapshot();
    }

    // Use resized image if available
    using var sourceImage = resizedImage ?? SKImage.FromBitmap(bitmap);

    // Convert to grayscale if specified
    using SKImage grayscaleImage = null;
    if (grayscale)
    {
        using var colorMatrix = new SKColorMatrix();
        colorMatrix.SetSaturation(0);
        using var filter = SKImageFilter.CreateColorMatrix(colorMatrix);
        using var paint = new SKPaint { ImageFilter = filter };
        using var surface = SKSurface.Create(new SKImageInfo(sourceImage.Width, sourceImage.Height));
        surface.Canvas.DrawImage(sourceImage, 0, 0, paint);
        grayscaleImage = surface.Snapshot();
    }

    // Set PNG compression level
    var options = new SKPngEncoderOptions { ZLibLevel = zlibLevel };
    using var encodedData = (grayscaleImage ?? sourceImage).Encode(options);
    return encodedData.ToArray();
}
