```javascript
import React, { useRef, useState } from 'react';
import Svg, { Circle, Polyline } from 'react-native-svg';
import { View } from 'react-native';
import { PanGestureHandler } from 'react-native-gesture-handler';

const DrawingComponent = ({ points, onBatchComplete }) => {
  const [lines, setLines] = useState([]);
  const [currentLine, setCurrentLine] = useState([]);
  const [currentPoint, setCurrentPoint] = useState(null);

  const findClosestPoint = (x, y) => {
    let minDist = Infinity;
    let closest = null;

    points.forEach(point => {
      const px = point.x;
      const py = point.y;
      const dist = (px - x) ** 2 + (py - y) ** 2;
      if (dist < 2500 && dist < minDist) {
        minDist = dist;
        closest = { x: px, y: py };
      }
    });

    return closest;
  };

  const onGestureEvent = event => {
    const { x, y } = event.nativeEvent;
    const closest = findClosestPoint(x, y);

    if (closest && currentLine.length === 0) {
      setCurrentLine([closest.x, closest.y]);
      setCurrentPoint(closest);
    } else if (currentLine.length > 0) {
      setCurrentLine([...currentLine, x, y]);
    }
  };

  const onHandlerStateChange = event => {
    if (event.nativeEvent.oldState === 4 && currentLine.length > 2) {
      setLines([...lines, [...currentLine]]);
      setCurrentLine([]);
      setCurrentPoint(null);
      onBatchComplete();
    }
  };

  return (
    <PanGestureHandler
      onGestureEvent={onGestureEvent}
      onHandlerStateChange={onHandlerStateChange}
    >
      <Svg height="100%" width="100%">
        {points.map((point, index) => (
          <Circle
            key={index}
            cx={point.x}
            cy={point.y}
            r={10}
            fill="red"
          />
        ))}
        {lines.map((line, index) => (
          <Polyline
            key={index}
            points={line.map((p, i) => (i % 2 === 0 ? `${p},` : `${p} `)).join('')}
            stroke="blue"
            strokeWidth={2}
            fill="none"
          />
        ))}
        {currentLine.length > 0 && (
          <Polyline
            points={currentLine.map((p, i) => (i % 2 === 0 ? `${p},` : `${p} `)).join('')}
            stroke="blue"
            strokeWidth={2}
            fill="none"
          />
        )}
      </Svg>
    </PanGestureHandler>
  );
};
```

