% Compute control points, normals, and tangents
function [panels, midpoints, normals, tangents, panel_lengths] = compute_control_points(points)
    n = size(points, 1) - 1;
    panels = {};
    midpoints = zeros(n, 2);
    normals = zeros(n, 2);
    tangents = zeros(n, 2);
    panel_lengths = zeros(n, 1);

    for j = 1:n
        x_a = points(j, 1);
        y_a = points(j, 2);
        x_b = points(j+1, 1);
        y_b = points(j+1, 2);
        panels{j} = [x_a, y_a, x_b, y_b];

        xm = (x_a + x_b)/2;
        ym = (y_a + y_b)/2;
        midpoints(j, :) = [xm, ym];

        dx = x_b - x_a;
        dy = y_b - y_a;
        L = sqrt(dx^2 + dy^2);
        panel_lengths(j) = L;

        tx = dx / L;
        ty = dy / L;
        tangents(j, :) = [tx, ty];

        nx = dy / L;
        ny = -dx / L;
        normals(j, :) = [nx, ny];
    end
end

% Compute influence matrix using 3-point Gauss quadrature
function A = compute_influence_matrix(midpoints, normals, panels, panel_lengths)
    n = length(panels);
    A = zeros(n);
    gauss_points = [-sqrt(3/5), 5/9; 0, 8/9; sqrt(3/5), 5/9];

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        nx_i = normals(i, 1);
        ny_i = normals(i, 2);

        for j = 1:n
            if i == j
                A(i, j) = 0.5;
            else
                x_a_j = panels{j}(1);
                y_a_j = panels{j}(2);
                x_b_j = panels{j}(3);
                y_b_j = panels{j}(4);
                L_j = panel_lengths(j);

                integral = 0;
                for k = 1:size(gauss_points, 1)
                    s = gauss_points(k, 1);
                    w = gauss_points(k, 2);

                    x_jk = x_a_j + (x_b_j - x_a_j)*(s + 1)/2;
                    y_jk = y_a_j + (y_b_j - y_a_j)*(s + 1)/2;

                    dx = x_i - x_jk;
                    dy = y_i - y_jk;
                    dist_sq = dx^2 + dy^2;
                    if dist_sq < 1e-12
                        continue;
                    end

                    dot_product = dx*nx_i + dy*ny_i;
                    integrand = dot_product / dist_sq;
                    contrib = integrand * w;
                    integral = integral + contrib;
                end
                integral = integral * (L_j / 2);
                A(i, j) = integral / (2 * pi);
            end
        end
    end
end

% Compute RHS of the system
function rhs = compute_rhs(alpha_deg, Vinf, normals)
    alpha_rad = deg2rad(alpha_deg);
    n = size(normals, 1);
    rhs = zeros(n, 1);

    for i = 1:n
        nx = normals(i, 1);
        ny = normals(i, 2);
        Vn = Vinf * (cos(alpha_rad)*nx + sin(alpha_rad)*ny);
        rhs(i) = -Vn;
    end
end

% Compute pressure coefficients
function [cp, theta, cp_analytical] = compute_cp(Vinf, alpha_deg, sigma, panels, midpoints, normals, tangents, panel_lengths)
    n = length(panels);
    cp = zeros(n, 1);
    theta = zeros(n, 1);
    cp_analytical = zeros(n, 1);
    valid = true;

    try
        for i = 1:n
            x_i = midpoints(i, 1);
            y_i = midpoints(i, 2);
            theta(i) = atan2(y_i, x_i);
            cp_analytical(i) = 1 - 4 * sin(theta(i))^2;
        end
    catch
        valid = false;
    end

    for i = 1:n
        tx = tangents(i, 1);
        ty = tangents(i, 2);
        u_ind = 0;
        v_ind = 0;

        for j = 1:n
            x_a_j = panels{j}(1);
            y_a_j = panels{j}(2);
            x_b_j = panels{j}(3);
            y_b_j = panels{j}(4);
            L_j = panel_lengths(j);
            sigma_j = sigma(j);

            for k = 1:3
                s = [-sqrt(3/5), 0, sqrt(3/5)];
                w = [5/9, 8/9, 5/9];
                s_val = s(k);
                w_val = w(k);

                x_jk = x_a_j + (x_b_j - x_a_j)*(s_val + 1)/2;
                y_jk = y_a_j + (y_b_j - y_a_j)*(s_val + 1)/2;

                dx = midpoints(i, 1) - x_jk;
                dy = midpoints(i, 2) - y_jk;
                dist_sq = dx^2 + dy^2;
                if dist_sq < 1e-12
                    continue;
                end

                factor = sigma_j * w_val * (L_j / 2) / (2 * pi * dist_sq);
                u_contribution = dx * factor;
                v_contribution = dy * factor;
                u_ind = u_ind + u_contribution;
                v_ind = v_ind + v_contribution;
            end

            u_fs = Vinf * cos(deg2rad(alpha_deg));
            v_fs = Vinf * sin(deg2rad(alpha_deg));
            u_total = u_ind + u_fs;
            v_total = v_ind + v_fs;
            Vt = u_total * tx + v_total * ty;
            cp(i) = 1 - (Vt / Vinf)^2;
        end
    end

    if ~valid
        theta = [];
        cp_analytical = [];
    end
end

% Compute lift coefficient (zero for source-only method)
