        % Panel length
        dx = x_b - x_a;
        dy = y_b - y_a;
        L = sqrt(dx^2 + dy^2);
        panel_lengths(j) = L;

        % Tangent vector
        tx = dx / L;
        ty = dy / L;
        tangents(j, :) = [tx ty];

        % Normal vector (pointing outward)
        nx = dy / L;
        ny = -dx / L;
