                y_a_j = panels(j, 2);
                x_b_j = panels(j, 3);
                y_b_j = panels(j, 4);
                L_j = panel_lengths(j);

                sum_integral = 0;
                for k = 1:size(gauss_points, 1)
                    s = gauss_points(k, 1);
                    w = gauss_points(k, 2);

                    % Position on panel j
                    x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                    y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;

                    % Distance from control point i to current point on panel j
                    dx = x_i - x_jk;
                    dy = y_i - y_jk;
