function integral = influence_coefficients(panel_i, panel_j, midpoint_i, normal_i, is_vortex)
    % Compute influence coefficients using 3-point Gauss quadrature
    x1j = panel_j(1);
    y1j = panel_j(2);
    x2j = panel_j(3);
    y2j = panel_j(4);
    x_i = midpoint_i(1);
    y_i = midpoint_i(2);
    nx_i = normal_i(1);
    ny_i = normal_i(2);

    % 3-point Gauss quadrature points and weights
    gauss_points = [-sqrt(3/5), 5/9; 0.0, 8/9; sqrt(3/5), 5/9];
    integral = 0.0;

    for k = 1:size(gauss_points, 1)
        s = gauss_points(k, 1);
        w = gauss_points(k, 2);

        % Position on panel j
        x_jk = x1j + (x2j - x1j) * (s + 1) / 2;
        y_jk = y1j + (y2j - y1j) * (s + 1) / 2;

        % Distance from point i to current point on panel j
        dx = x_i - x_jk;
        dy = y_i - y_jk;
        dist_sq = dx^2 + dy^2;

        if dist_sq < 1e-12
            continue;
        end

        if is_vortex
            % Vortex influence: (dy * nx - dx * ny) / dist_sq
            contrib = (dy * nx_i - dx * ny_i) / dist_sq * w;
        else
            % Source influence: (dx * nx + dy * ny) / dist_sq
            contrib = (dx * nx_i + dy * ny_i) / dist_sq * w;
        end

        integral = integral + contrib;
    end

    integral = integral / (2 * pi);
end

function A = compute_influence_matrix(midpoints, normals, panels, panel_lengths)
    % Build influence matrix with source and vortex contributions
    n = size(panels, 1);
    A = zeros(n + 1);

    for i = 1:n
        for j = 1:n
            A(i, j) = influence_coefficients(panels(i, :), panels(j, :), midpoints(i, :), normals(i, :), false);
            A(i, n + 1) = A(i, n + 1) + influence_coefficients(panels(i, :), panels(j, :), midpoints(i, :), normals(i, :), true);
        end
    end

    % Kutta condition: γ₁ + γₙ = 0
    A(n + 1, 1) = 1;
    A(n + 1, n) = 1;
    A(n + 1, n + 1) = 0; % γ₁ + γₙ = 0
end

function rhs = compute_rhs(alpha_deg, Vinf, normals)
