    end
end

function [cp, theta, cp_analytical] = compute_pressure_coefficients(Vinf, alpha_deg, sigma, gamma, panels, midpoints, normals, tangents, panel_lengths)
    % Compute pressure coefficients at each panel
    n = size(panels, 1);
    cp = zeros(n, 1);

    % Try to compute angles for analytical solution (circular cylinder)
    try
        theta = atan2(midpoints(:, 2), midpoints(:, 1));
        cp_analytical = 1.0 - 4.0 * sin(theta).^2;
    catch
        theta = [];
        cp_analytical = [];
    end

    alpha = deg2rad(alpha_deg);
    u_fs = Vinf * cos(alpha);
    v_fs = Vinf * sin(alpha);

    for i = 1:n
        xi = midpoints(i, 1);
        yi = midpoints(i, 2);
        tx = tangents(i, 1);
        ty = tangents(i, 2);

        u_ind = 0.0;
        v_ind = 0.0;

        for j = 1:n
            x1j = panels(j, 1);
            y1j = panels(j, 2);
            x2j = panels(j, 3);
            y2j = panels(j, 4);
            Lj = panel_lengths(j);

            % Source contribution
            gauss_points = [-sqrt(3/5), 5/9; 0.0, 8/9; sqrt(3/5), 5/9];
            for k = 1:size(gauss_points, 1)
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                xjk = x1j + (x2j - x1j) * (s + 1) / 2;
                yjk = y1j + (y2j - y1j) * (s + 1) / 2;

                % Distance from point i to current point on panel j
                dx = xi - xjk;
                dy = yi - yjk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    continue;
                end

                % Source contribution
                factor = sigma(j) * w * (Lj / 2) / (2 * pi * dist_sq);
                u_ind = u_ind + dx * factor;
                v_ind = v_ind + dy * factor;
            end

            % Vortex contribution
            for k = 1:size(gauss_points, 1)
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);

                % Position on panel j
                xjk = x1j + (x2j - x1j) * (s + 1) / 2;
                yjk = y1j + (y2j - y1j) * (s + 1) / 2;

                % Distance from point i to current point on panel j
                dx = xi - xjk;
                dy = yi - yjk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    continue;
                end

                % Vortex contribution
                factor = gamma * w * (Lj / 2) / (2 * pi * dist_sq);
                u_ind = u_ind - dy * factor;
                v_ind = v_ind + dx * factor;
            end
        end

        % Total velocity components
        u_total = u_ind + u_fs;
        v_total = v_ind + v_fs;

        % Tangential velocity
        Vt = u_total * tx + v_total * ty;

        % Pressure coefficient
        cp(i) = 1.0 - (Vt / Vinf)^2;
    end
end

function Cl = compute_cl(Vinf, gamma, panel_lengths, chord)
    % Compute lift coefficient using Kutta-Joukowski theorem
    Gamma = gamma * sum(panel_lengths);
    Cl = (2 * Gamma) / (Vinf * chord);
end

