// Batch insert function with parallel processing
const insertBatch = async (batch, workerId) => {
    if (batch.length === 0) return;

    // Implement parallel processing using PostgreSQL COPY command
    const columns = Object.keys(batch[0]).join(', ');
    const values = batch.map((row, i) => 
        `(${Object.values(row).map((_, j) => 
            `$${i * Object.keys(row).length + j + 1}`
        ).join(', ')})`
    ).join(', ');

    const flatValues = batch.flatMap(Object.values);

    try {
        // Use a separate database client for parallel operations
        const tempClient = new Client(JSON.parse(dbConfig));
        await tempClient.connect();
        await tempClient.query(`INSERT INTO customers (${columns}) VALUES ${values}`, flatValues);
        await tempClient.end();
    } catch (err) {
        throw err;
