};

// Function to split CSV into chunks for parallel processing
const splitCSV = (filePath, numChunks) => {
    return new Promise((resolve, reject) => {
        const chunkPaths = [];
        const fileSize = fs.statSync(filePath).size;
        const chunkSize = Math.ceil(fileSize / numChunks);

        const readStream = fs.createReadStream(filePath);

        let chunkNumber = 0;
        let currentChunk = 0;
        let startPosition = 0;

        readStream.on('open', () => {
            const header = readStream.read(1024);
            if (!header) {
                reject(new Error('Unable to read file header'));
                return;
            }

            const headerString = header.toString();
            const headerEnd = headerString.indexOf('\n');
            const csvHeader = headerString.substring(0, headerEnd + 1);

            startPosition = headerEnd + 1;

            for (let i = 0; i < numChunks; i++) {
                const chunkPath = `${filePath}.part${i}`;
                const writeStream = fs.createWriteStream(chunkPath);

                // Write CSV header to each chunk
                writeStream.write(csvHeader);
                chunkPaths.push(chunkPath);
            }

            readStream.pause();
            processChunks(readStream, chunkPaths, startPosition, chunkSize, 0, resolve, reject);
        });
    });
};

// Helper function to process file chunks
const processChunks = (readStream, chunkPaths, position, chunkSize, chunkIndex, resolve, reject) => {
    if (chunkIndex >= chunkPaths.length) {
        resolve(chunkPaths);
        return;
    }

    const writeStream = fs.createWriteStream(chunkPaths[chunkIndex], { flags: 'a' });
    let currentSize = 0;

    readStream.seek(position);
    readStream.resume();

    const writeChunk = () => {
        let chunk;
        while ((chunk = readStream.read(Math.min(16384, chunkSize - currentSize))) {
            currentSize += chunk.length;
            writeStream.write(chunk);

            if (currentSize >= chunkSize) {
                writeStream.end();
                // Find next line break to avoid cutting records
                const nextStream = fs.createReadStream(chunkPaths[chunkIndex]);
                let lastLineBreak = 0;
                let buffer = Buffer.alloc(0);

                nextStream.on('data', (data) => {
                    const newBuffer = Buffer.concat([buffer, data]);
                    let lineBreak;

                    while ((lineBreak = newBuffer.indexOf('\n')) !== -1) {
                        lastLineBreak += lineBreak + 1;
                        newBuffer.copy(newBuffer, 0, lineBreak + 1);
                        newBuffer.length -= lineBreak + 1;
                    }

                    buffer = newBuffer;
                });

                nextStream.on('end', () => {
                    if (lastLineBreak > 0) {
                        // Truncate the file to remove incomplete last line
                        fs.truncateSync(chunkPaths[chunkIndex], lastLineBreak);
                    }

                    process.nextTick(() => 
                        processChunks(
                            readStream,
                            chunkPaths,
                            position + currentSize,
                            chunkSize,
                            chunkIndex + 1,
                            resolve,
                            reject
                        )
                    );
                });

                return;
            }
        }
    };

    readStream.on('readable', writeChunk);

    readStream.on('end', () => {
        writeStream.end();
        process.nextTick(() => 
            processChunks(
                readStream,
                chunkPaths,
                position + currentSize,
                chunkSize,
                chunkIndex + 1,
                resolve,
                reject
            )
        );
    });

    readStream.on('error', reject);
    writeStream.on('error', reject);
};

// Function to process a single CSV chunk
const processCSVChunk = async (chunkPath, workerId) => {
    return new Promise((resolve, reject) => {
        try {
            const stream = fs.createReadStream(chunkPath);
            const batch = [];

            const query = papaparse.parse(stream, {
                header: true,
                skipEmptyLines: true,
                step: async (results, parser) => {
                    batch.push(results.data);

                    if (batch.length >= batchSize) {
                        await insertBatch(batch, workerId);
                        batch.length = 0; // Clear batch
                    }
                },
                complete: async () => {
                    if (batch.length > 0) {
                        await insertBatch(batch, workerId);
                    }

                    // Clean up chunk file
                    fs.unlinkSync(chunkPath);
                    resolve();
                },
                error: (err) => {
                    reject(err);
                }
            });
        } catch (err) {
            reject(err);
        }
    });
};

// Main processing function with multiprocessing
const processCSV = async () => {
    try {
        await client.connect();

        // Get total file size for progress tracking
        const stats = fs.statSync(csvPath);
        const totalSize = stats.size;
        let processedSize = 0;

        // Split CSV into chunks for parallel processing
        const numWorkers = Math.max(1, os.cpus().length - 1);
        const chunkPaths = await splitCSV(csvPath, numWorkers);

        // Track total records processed
        let totalRecords = 0;

        // Process chunks in parallel
        const processingPromises = chunkPaths.map((chunkPath, index) => 
            processCSVChunk(chunkPath, index + 1)
                .then(() => {
                    // Update progress in Redis
                    redis.incrby(`progress:${fileId}`, Math.floor(100 / numWorkers));
                })
                .catch(async (err) => {
                    await sendNotification(false, err.message);
                    throw err;
                })
        );

        await Promise.all(processingPromises);

        // Update final progress
        await redis.set(`progress:${fileId}`, '100');

        // Clean up original file
        fs.unlinkSync(csvPath);

        await sendNotification(true);
        await client.end();
    } catch (err) {
        await sendNotification(false, err.message);
        await client.end();
    }
};

processCSV();
