// item.service.ts
import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { Item, ItemDocument } from './schemas/item.schema';
import { XmlItem, XmlLoaderService } from './xml/xml-loader.service';
import { parseStringPromise } from 'xml2js';
import { readFileSync } from 'fs';
import { join } from 'path';

@Injectable()
export class ItemService {
  private xmlItems: XmlItem[] = [];

  constructor(
    @InjectModel('Item') private readonly itemModel: Model<ItemDocument>,
    private readonly xmlLoaderService: XmlLoaderService
  ) {}

  async onModuleInit() {
    await this.loadXmlData();
    await this.migrateToMongo();
  }

  private async loadXmlData() {
    this.xmlItems = await this.xmlLoaderService.loadItems();
  }

  private async migrateToMongo(): Promise<number> {
    const result = await this.itemModel.deleteMany({});
    if (result.deletedCount !== undefined) {
      const items = this.xmlItems.map(item => ({
        id: item.Id,
        name: item.Name
      }));

      await this.itemModel.insertMany(items);
      return items.length;
    }
    return 0;
  }

  getFromXml(name?: string): XmlItem[] {
    if (name) {
      return this.xmlItems.filter(
        item => item.Name.toLowerCase().includes(name.toLowerCase())
      );
    }
    return this.xmlItems;
  }

  async getFromMongo(name?: string): Promise<Item[]> {
    if (name) {
      return this.itemModel.find({
        name: { $regex: name, $options: 'i' }
      });
    }
    return this.itemModel.find();
  }
}
