// items.service.ts - Nest.js service with XML and MongoDB integration
import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { Item, ItemDocument } from './item.schema';
import * as xml2js from 'xml2js';
import * as fs from 'fs';
import * as path from 'path';

@Injectable()
export class ItemsService {
  private xmlItems: Item[] = [];

  constructor(@InjectModel(Item.name) private itemModel: Model<ItemDocument>) {}

  async onModuleInit() {
    await this.loadXmlData();
    await this.migrateToMongo();
  }

  private async loadXmlData() {
    try {
      const xmlPath = path.join(__dirname, '..', 'data', 'items.xml');
      const xmlData = fs.readFileSync(xmlPath, 'utf-8');

      const result = await xml2js.parseStringPromise(xmlData);

      if (result && result.Items && result.Items.Item) {
        this.xmlItems = result.Items.Item.map(item => ({
          id: item.Id[0],
          name: item.Name[0],
          category: item.Category ? item.Category[0] : 'Uncategorized',
          price: parseFloat(item.Price[0])
        }));
      }
    } catch (error) {
      console.error(`XML Load Error: ${error.message}`);
    }
  }

  private async migrateToMongo() {
    try {
      // Clear existing data
      await this.itemModel.deleteMany({});

      // Insert XML data into MongoDB
      if (this.xmlItems.length > 0) {
        const result = await this.itemModel.insertMany(this.xmlItems);
        return result.length;
      }
      return 0;
    } catch (error) {
      throw new Error(`Migration failed: ${error.message}`);
    }
  }

  create(createItemDto: CreateItemDto) {
    return this.itemModel.create(createItemDto);
  }

  findAll(name?: string) {
    const query = name ? { name: { $regex: name, $options: 'i' } } : {};
    return this.itemModel.find(query);
  }

  findOne(id: string) {
    return this.itemModel.findOne({ id });
  }

  // SQL to MongoDB query examples
  async sqlQueryExamples(queryType: string) {
    switch (queryType) {
      case 'simple_filter':
        // SQL: SELECT * FROM items WHERE price > 10
        // MongoDB: db.items.find({price: {$gt: 10}})
        return this.itemModel.find({ price: { $gt: 10 } });

      case 'text_search':
        // SQL: SELECT * FROM items WHERE name LIKE '%apple%'
        // MongoDB: db.items.find({name: /apple/i})
        return this.itemModel.find({ name: { $regex: 'apple', $options: 'i' } });

      case 'grouped_aggregation':
        // SQL: SELECT category, COUNT(*) FROM items GROUP BY category
        // MongoDB: db.items.aggregate([{$group: {_id: "$category", count: {$sum: 1}}}])
        return this.itemModel.aggregate([
          {
            $group: {
              _id: "$category",
              count: { $sum: 1 }
            }
          }
        ]);

      case 'join_equivalent':
        // SQL: SELECT * FROM items i JOIN categories c ON i.category_id = c.id
        // MongoDB: db.items.aggregate([{$lookup: {from: "categories", localField: "category_id", foreignField: "_id", as: "category_info"}}])
        return this.itemModel.aggregate([
          {
            $lookup: {
              from: 'categories',
              localField: 'category_id',
              foreignField: '_id',
              as: 'category_info'
            }
          }
        ]);

      default:
        return this.itemModel.find();
    }
  }
}
