const fs = require('fs/promises');
const sharp = require('sharp');

/**
 * Adjusts watermark opacity and resizes it
 * @param {Buffer} watermarkBuffer - Original watermark image buffer
 * @param {number} width - Target width
 * @param {height} height - Target height
 * @param {number} opacity - Opacity level (0.0-1.0)
 * @returns {Promise<Buffer>} Processed watermark buffer
 */
async function adjustWatermarkOpacity(watermarkBuffer, width, height, opacity) {
  const data = await sharp(watermarkBuffer)
    .resize(width, height)
    .ensureAlpha()
    .toFormat('raw')
    .toBuffer();

  const pixels = new Uint8Array(data);
  for (let i = 3; i < pixels.length; i += 4) {
    pixels[i] = Math.round(pixels[i] * opacity);
  }

  return sharp(pixels, {
    raw: {
      width, height, channels: 4
    }
  }).toFormat('png').toBuffer();
}

/**
 * Calculates variance in a specific image region
 * @param {Buffer} imageBuffer - Image buffer
 * @param {number} x - X coordinate of region
 * @param {number} y - Y coordinate of region
 * @param {number} width - Width of region
 * @param {number} height - Height of region
 * @param {number} downscaleFactor - Factor to downscale ROI for efficiency
 * @returns {Promise<number>} Calculated variance
 */
async function calculateVariance(imageBuffer, x, y, width, height, downscaleFactor = 4) {
  try {
    // Extract ROI and apply preprocessing for robust analysis
    const roiData = await sharp(imageBuffer)
      .extract({ left: x, top: y, width, height })
      .grayscale()
      .median(3)  // Reduce noise
      .resize(Math.max(1, Math.round(width / downscaleFactor)), 
              Math.max(1, Math.round(height / downscaleFactor)))
      .toBuffer({ raw: true });

    const pixels = new Uint8Array(roiData.buffer);
    if (pixels.length === 0) return Infinity;

    // Calculate mean and variance
    let sum = 0;
    for (let p of pixels) sum += p;
    const mean = sum / pixels.length;

    let variance = 0;
    for (let p of pixels) variance += Math.pow(p - mean, 2);
    return variance / pixels.length;
  } catch (err) {
    // Return maximum variance for failed regions
    return Infinity;
  }
}

/**
 * Adds a watermark to an image with smart placement
 * @param {string} imagePath - Path to original image
 * @param {string} watermarkPath - Path to watermark image
 * @param {string} outputImagePath - Path for output image
 * @param {Object} options - Processing options
 * @returns {Promise<string>} Path to output image
 */
async function addWatermarkToImage(imagePath, watermarkPath, outputImagePath, options = {}) {
  const {
    watermarkOpacity = 0.5,
    watermarkRatio = 0.2
  } = options;

  try {
    // Read original image
    const image = sharp(imagePath);
    const metadata = await image.metadata();
    const { width: originalWidth, height: originalHeight } = metadata;

    // Calculate watermark dimensions
    const watermarkWidth = Math.round(originalWidth * watermarkRatio);
    const watermarkHeight = Math.round(originalHeight * watermarkRatio);

    // Read and process watermark
    const watermarkData = await fs.promises.readFile(watermarkPath);
    const processedWatermark = await adjustWatermarkOpacity(
      watermarkData, watermarkWidth, watermarkHeight, watermarkOpacity
    );

    // Define corners with bounds checking
    const corners = {
      'top-left':     { x: 0, y: 0 },
      'top-right':    { x: Math.max(0, originalWidth - watermarkWidth), y: 0 },
      'bottom-left':  { x: 0, y: Math.max(0, originalHeight - watermarkHeight) },
      'bottom-right': { x: Math.max(0, originalWidth - watermarkWidth), 
                        y: Math.max(0, originalHeight - watermarkHeight) }
    };

    // Read original image buffer
    const imageBuffer = await image.toBuffer();

    // Analyze corners to find the best one
    let bestCorner = 'top-left';
    let minVariance = Infinity;

    // Process each corner
    await Promise.all(Object.entries(corners).map(async ([name, pos]) => {
      // Skip invalid corners
      if (pos.x < 0 || pos.y < 0 || watermarkWidth <= 0 || watermarkHeight <= 0) {
        return;
      }

      try {
        const variance = await calculateVariance(imageBuffer, pos.x, pos.y, watermarkWidth, watermarkHeight);
        if (variance < minVariance) {
          minVariance = variance;
          bestCorner = name;
        }
      } catch (err) {
        console.error(`Error processing ${name}:`, err);
      }
    }));

    // Composite watermark at best corner
    const { x, y } = corners[bestCorner];

    await sharp(imageBuffer)
      .composite([{
        input: processedWatermark,
        left: x,
        top: y,
        blend: 'over'
      }])
      .toFile(outputImagePath);

    return outputImagePath;
  } catch (err) {
    throw new Error(`Watermarking failed: ${err.message}`);
  }
}

