        NeuralNetwork network(0.01);

        // Create different types of neurons
        auto n1 = std::make_shared<Neuron>(Neuron::NeuronType::FAST_SPIKING);
        auto n2 = std::make_shared<Neuron>(Neuron::NeuronType::REGULAR_SPIKING);
        auto n3 = std::make_shared<Neuron>(Neuron::NeuronType::BURSTING);

