### ✅ MATLAB Code for RSA Key Generation

```matlab
function [publicKey, privateKey] = generateRSAKeys()
    % Step 1: Generate two large random prime numbers p and q
    % For demonstration, small primes are used
    p = randomPrime(100, 1000);
    q = randomPrime(100, 1000);
    while isequal(p, q)
        q = randomPrime(100, 1000); % Ensure p and q are distinct
    end

    % Step 2: Compute the modulus n = p * q
    n = p * q;

    % Step 3: Compute Euler's totient phi(n) = (p-1)*(q-1)
    phi = (p - 1) * (q - 1);

    % Step 4: Choose public exponent e (commonly 65537)
    e = 65537;
    while gcd(e, phi) ~= 1
        e = randi([2, phi-1], 1);
    end

    % Step 5: Compute private exponent d = e^(-1) mod phi(n)
    % MATLAB's modinverse function computes the modular inverse
    d = modinverse(e, phi);

    % Return public key (e, n) and private key (d, n)
    publicKey = [e, n];
    privateKey = [d, n];
end

% Helper function to generate a random prime in the given range
function prime = randomPrime(lower, upper)
    candidate = randi([lower, upper], 1);
    while ~isprime(candidate)
        candidate = randi([lower, upper], 1);
    end
    prime = candidate;
end
