    "By the power of nature's bounty,",
    "With these sacred ingredients,",
    "Through the magic of creation,",
    "In harmony with nature's will,",
    "With gratitude to the earth,"
  ];
  spellLines.push(invocations[Math.floor(Math.random() * invocations.length)]);

  // Add main spell components
  for (let category in effectsByCategory) {
    // Select a few effects to include
    const selectedEffects = effectsByCategory[category].slice(0, 2);

    for (let effectData of selectedEffects) {
      const lines = [
        `Let the ${effectData.ingredient} ${effectData.effect},`,
        `May the essence of ${effectData.ingredient} bring ${effectData.effect.split(' ')[0]} ${category},`,
        `With the power of ${effectData.ingredient} to ${effectData.effect},`
      ];
      spellLines.push(lines[Math.floor(Math.random() * lines.length)]);
    }
  }

  // Add closing line
  const closings = [
    "So it is written, so it shall be.",
    "The magic is sealed with these sacred elements.",
    "By the power of nature's gifts, this spell takes form.",
    "The energies align, the spell is complete.",
    "With this incantation, the magic unfolds."
  ];
  spellLines.push(closings[Math.floor(Math.random() * closings.length)]);

  return spellLines.join('\n');
}
