public class TableGeometryEmbedder
{
    /// <summary>
    /// Embeds drawing primitives into a specified McTable cell.
    /// </summary>
    /// <param name="table">The target McTable object.</param>
    /// <param name="rowIndex">Zero-based row index of the target cell.</param>
    /// <param name="columnIndex">Zero-based column index of the target cell.</param>
    /// <param name="entityGeometryList">List of EntityGeometry objects to embed.</param>
    public void EmbedPrimitivesToTableCell(
        McTable table, 
        int rowIndex, 
        int columnIndex, 
        List<EntityGeometry> entityGeometryList)
    {
        if (table == null)
            throw new ArgumentNullException(nameof(table));
        if (entityGeometryList == null)
            throw new ArgumentNullException(nameof(entityGeometryList));

        Document doc = Application.DocumentManager.MdiActiveDocument;
        Database db = doc.Database;

        using (Transaction tr = db.TransactionManager.StartTransaction())
        {
            try
            {
                // Validate row and column indices
                if (rowIndex < 0 || rowIndex >= table.Rows.Count)
                    throw new ArgumentOutOfRangeException(nameof(rowIndex), "Row index out of range");
                if (columnIndex < 0 || columnIndex >= table.Columns.Count)
                    throw new ArgumentOutOfRangeException(nameof(columnIndex), "Column index out of range");

                // Get the target cell
                McRow row = table.Rows[rowIndex];
                McCell cell = row.Cells[columnIndex];

                // Start a block transaction to add entities to the cell
                cell.Geometry.OpenForModify();

                // Embed each geometry into the cell
                foreach (EntityGeometry geometry in entityGeometryList)
                {
                    // Convert or embed the geometry (example operation)
                    ObjectId entityId = cell.Geometry.Append(geometry);
                    // Optional: Set additional properties on the entity
                }

                // Commit changes to the cell geometry
                cell.Geometry.Commit();

                // Commit the transaction
                tr.Commit();
            }
            catch (Exception ex)
            {
                tr.Abort();
                Application.ShowAlertDialog("Error embedding geometry: " + ex.Message);
                throw;
            }
        }
    }
}
